    debug('Getting embedding response');
    try {
      const embeddingResponse = await this.openai.embeddings.create({
        model: this.embeddingModelName,
        input,
      });

      return embeddingResponse.data[0].embedding;
    } catch (error) {
      debug('Embedding error:', error);
      return undefined;
    }
  }
}

