```javascript
// From report_template.html - Dynamic table rendering
function renderDetailedRuns(rawResults) {
    const tbody = document.getElementById('detailed-runs-tbody');

    if (!rawResults || rawResults.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="text-center">No run data available.</td></tr>';
        return;
    }

    // Store original data for sorting/filtering
    window.runData = rawResults;

    // Add search functionality
    addTableSearch();

    // Render initial table
    renderRunsTable(rawResults);
}

function renderRunsTable(runs) {
    const tbody = document.getElementById('detailed-runs-tbody');
    tbody.innerHTML = '';

    runs.forEach(run => {
        const row = document.createElement('tr');

        // Create cells for each column
        const runIdCell = document.createElement('td');
        runIdCell.textContent = run.run_id;
        row.appendChild(runIdCell);

        const statusCell = document.createElement('td');
        statusCell.innerHTML = `<span class="status ${run.success ? 'success' : 'error'}">${run.success ? '✅ Success' : '❌ Failed'}</span>`;
        row.appendChild(statusCell);

        const paramsCell = document.createElement('td');
        paramsCell.textContent = formatParameters(run.parameters);
        row.appendChild(paramsCell);

        const timeCell = document.createElement('td');
        timeCell.textContent = `${run.execution_time.toFixed(2)}s`;
        row.appendChild(timeCell);

        const tokensCell = document.createElement('td');
        tokensCell.textContent = run.total_tokens || 'N/A';
        row.appendChild(tokensCell);

        const evaluationsCell = document.createElement('td');
        evaluationsCell.textContent = run.evaluations ? run.evaluations.length : 0;
        row.appendChild(evaluationsCell);

        tbody.appendChild(row);
    });
}

// Search functionality
function addTableSearch() {
    const searchInput = document.createElement('input');
    searchInput.type = 'text';
    searchInput.placeholder = 'Search runs...';
    searchInput.className = 'table-search';
    searchInput.addEventListener('input', (e) => {
        const searchTerm = e.target.value.toLowerCase();
        const filteredRuns = window.runData.filter(run => 
            run.run_id.toLowerCase().includes(searchTerm) ||
            (run.parameters && JSON.stringify(run.parameters).toLowerCase().includes(searchTerm))
        );
        renderRunsTable(filteredRuns);
    });

    const tableContainer = document.querySelector('.table-container');
    tableContainer.insertBefore(searchInput, tableContainer.firstChild);
}
```

