export async function stringContainsEvaluator(
  evaluation: StringContainsEvaluation,
  context: EvaluationContext
): Promise<EvaluationResult> {
  const { expected_value, case_sensitive = false } = evaluation;
  const actual_output = context.output || '';

  const found = case_sensitive 
    ? actual_output.includes(expected_value)
    : actual_output.toLowerCase().includes(expected_value.toLowerCase());

  return {
    evaluator_type: 'string_contains',
    success: found,
    summary: found 
      ? `Assertion PASSED: Agent response contained the expected substring.`
      : `Assertion FAILED: Agent response did not contain '${expected_value}'.`,
    details: {
      expected_value,
      actual_output,
      case_sensitive,
    },
  };
}
