## `@sint/eliza-plugin` — 20-line implementation sketch

The plugin hooks into Eliza's `IAgentRuntime` using the existing `processActions` middleware pattern. Every tool call passes through `PolicyGateway.enforce()` before execution:

```typescript
// packages/plugin-sint/src/index.ts
import { Plugin, IAgentRuntime, Memory, Action } from "@elizaos/core";
import { PolicyGateway, CapabilityToken } from "@sint/gate-policy-gateway";

export const sintPlugin: Plugin = {
  name: "sint",
  description: "Capability token enforcement for Eliza tool calls",

  init: async (config: SintConfig, runtime: IAgentRuntime) => {
    const gateway = new PolicyGateway({ rules: config.tierRules });

    // Wrap every registered action
    const originalActions = runtime.actions;
    runtime.actions = originalActions.map((action: Action) => ({
      ...action,
      handler: async (rt, msg, state, opts, cb) => {
        const token: CapabilityToken = await config.resolveToken(action.name, rt.agentId);
        await gateway.enforce(action.name, token);           // throws TokenInvalidError | TierEscalationRequired
        const result = await action.handler(rt, msg, state, opts, cb);
        config.onAudit?.({ action: action.name, agentId: rt.agentId, token, result });
        return result;
      },
    }));
  },
};

export default sintPlugin;
```

**Usage in `eliza.config.ts`:**
```typescript
import sintPlugin from "@sint/eliza-plugin";

export default {
  plugins: [sintPlugin],
  sint: {
    resolveToken: (toolName, agentId) => tokenStore.get(`${agentId}:${toolName}`),
    tierRules: [
      { resourcePattern: "solana://*", actions: ["transfer"], tier: "T3_commit" },
      { resourcePattern: "twitter://*", actions: ["post"],    tier: "T2_act"    },
      { resourcePattern: "twitter://*", actions: ["search"],  tier: "T0_observe"},
    ],
    onAudit: (event) => console.log("[sint]", event),
  },
}
```

**When a T3 action is triggered without a valid token:**
```
[sint] TokenInvalidError: agent/abc123 attempted solana://transfer without T3_commit capability
Action paused — awaiting human sign-off at https://sint.example.com/approvals/req_xyz
```

---

